import React, { useState } from "react";
import axios from "axios";

const Form = () => {
  const [inputValue, setInputValue] = useState("");
  const [frequency, setFrequency] = useState(null);
  const [errorMessage, setErrorMessage] = useState("");

  const handleChange = (event) => {
    setInputValue(event.target.value);
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    setErrorMessage("");
    setFrequency(null);
    
    try {
      const response = await axios.post("http://127.0.0.1:5000/predict", {
        name: inputValue,
      });
      
      setFrequency(response.data.frequency);
      setInputValue("");
    } catch (error) {
      console.error("Error sending data:", error);
      setErrorMessage("Failed to get frequency. Please try again.");
    }
  };

  return (
    <div className="flex flex-col items-center justify-center  bg-gray-100 px-4 bg-red-100">
      <h2 className="text-2xl font-semibold mb-4">React Form to Send Data to Flask</h2>
      <form onSubmit={handleSubmit} className="bg-white shadow-md rounded-lg p-6 w-full max-w-md">
        <input
          type="text"
          value={inputValue}
          onChange={handleChange}
          placeholder="Enter something..."
          required
          className="w-full p-2 border border-gray-300 rounded-lg mb-4 focus:outline-none focus:ring-2 focus:ring-blue-500"
        />
        <button
          type="submit"
          className="w-full bg-blue-500 text-white py-2 rounded-lg hover:bg-blue-600 transition duration-200"
        >
          Submit
        </button>
      </form>
      {frequency !== null && (
        <p className="mt-4 text-lg text-green-600 font-medium">Frequency: {frequency}</p>
      )}
      {errorMessage && (
        <p className="mt-4 text-lg text-red-500 font-medium">{errorMessage}</p>
      )}
    </div>
  );
};

export default Form;
